"""Build self-contained Phase-1 review HTML and machine-readable role matrix. Documentation only."""
from pathlib import Path
import json,csv,re,base64,html
from markdown_it import MarkdownIt
from PIL import Image
import io
R=Path(__file__).resolve().parents[1];D=R/'docs';C=R/'contracts'
model=json.loads((C/'logical-data-model.json').read_text()); req=json.loads((C/'requirements-register.json').read_text()); api=json.loads((C/'openapi.json').read_text())
# Role matrix CSV from the reviewed markdown table.
lines=(D/'03-role-permission-matrix.md').read_text().splitlines(); rows=[]; header=None
for line in lines:
 if line.startswith('| Capability |'):header=[x.strip() for x in line.strip('|').split('|')]
 elif header and line.startswith('|---'):continue
 elif header and line.startswith('|'):
  cells=[x.strip() for x in line.strip('|').split('|')]
  if len(cells)!=len(header):header=None;continue
  for role,value in zip(header[1:],cells[1:]):rows.append({'capability':cells[0],'role':role,'access':value,'policy_status':'PROPOSED','enforcement':'backend permission + ownership/geographic scope + assurance'})
 elif header:header=None
with (C/'role-permission-matrix.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
md=MarkdownIt('default',{'html':False,'linkify':False,'typographer':False}).enable('table')
def render(p):
 text=p.read_text()
 text=text.replace('![System architecture](diagrams/system-architecture.svg)','')
 # Resolve local doc links to in-page document anchors; external citations remain ordinary links.
 def link(m):
  label,target=m.group(1),m.group(2)
  if target.startswith(('http://','https://','#')):return m.group(0)
  name=target.split('#')[0].split('/')[-1]
  return f'[{label}](#doc-{name.replace(".","-")})'
 text=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',link,text)
 # Embedded image is replaced by a figure after rendering.
 text=text.replace('![System architecture](diagrams/system-architecture.svg)','')
 return md.render(text)
def data_img(p,maxw=1100):
 im=Image.open(p).convert('RGB');im.thumbnail((maxw,2400));b=io.BytesIO();im.save(b,'WEBP',quality=84,method=6)
 return 'data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()
def svg_inline(p):
 s=p.read_text();s=re.sub(r'<\?xml[^>]*\?>','',s);s=re.sub(r'<!DOCTYPE[^>]*>','',s)
 prefix='svg-'+p.stem+'-'
 ids=re.findall(r'\bid="([^"]+)"',s)
 for old in sorted(set(ids),key=len,reverse=True):
  s=s.replace('id="'+old+'"','id="'+prefix+old+'"').replace('href="#'+old+'"','href="#'+prefix+old+'"').replace('url(#'+old+')','url(#'+prefix+old+')')
 return s
counts={k:sum(r['source']==k for r in req) for k in ['master','shared-conversation','screenshot']}
ops=sum(len(v) for v in api['paths'].values())
docs=sorted(D.glob('*.md'))
nav=''.join(f'<a href="#doc-{p.name.replace(".","-")}">{html.escape(p.stem.replace("-"," ").title())}</a>' for p in docs)
reqrows=''.join('<tr data-source="'+r['source']+'"><td><code>'+html.escape(r['id'])+'</code></td><td>'+html.escape(r['source'])+'</td><td>'+html.escape(r['requirement'])+'</td><td>'+html.escape(r['phase'])+'</td><td>'+html.escape(r['status'])+'</td></tr>' for r in req)
diagrams=''.join('<details class="diagram"><summary>'+html.escape(p.stem.replace('-',' ').title())+'</summary><div class="svgwrap">'+svg_inline(p)+'</div><p class="muted">Source: docs/diagrams/'+p.name+' · zoom/scroll to inspect. Domain diagrams include full fields; complete overview shows every entity/relationship.</p></details>' for p in sorted((D/'diagrams').glob('*.svg')) if p.name!='system-architecture.svg')
images=[('Homepage','file_00000000ed6082109834425a8eadf979.png'),('Login / signup','file_00000000eaf48210a2930dd3061eba38.png'),('Admin','file_000000001458821082c41adcad8398e0.png'),('Vendor','file_000000001fd08210b38f6b50c3a01087.png'),('Rider','file_00000000a7508210a16ca15694141f4f.png')]
gallery=''.join('<details><summary>'+html.escape(name)+'</summary><img loading="lazy" alt="'+html.escape(name)+' reference" src="'+data_img(R/'references'/file)+'"></details>' for name,file in images)
docsections=''.join('<section class="doc" id="doc-'+p.name.replace('.','-')+'"><div class="eyebrow">DESIGN DOCUMENT · '+html.escape(p.name)+'</div>'+render(p)+'</section>' for p in docs)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Get Stoopy — Phase-1 Architecture Review</title><style>
:root{--red:#b30d1b;--ink:#15171a;--muted:#5d6570;--line:#e2e5e9;--soft:#f5f6f8;--gold:#c6a56b}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font:15px/1.65 system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:var(--ink);background:#fff}a{color:var(--red);text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #b30d1b;outline-offset:3px}.top{background:var(--ink);color:#fff;padding:12px 5vw;display:flex;justify-content:space-between;gap:16px;font-size:13px}.top strong{color:#fff}.hero{padding:46px 5vw 34px;border-bottom:1px solid var(--line);background:linear-gradient(110deg,#fff 65%,#fff5f5)}.eyebrow{font-size:11px;letter-spacing:.13em;font-weight:750;color:var(--red);text-transform:uppercase}.hero h1{font-size:clamp(30px,4vw,50px);line-height:1.12;margin:10px 0}.hero p{max-width:900px;color:var(--muted);font-size:17px}.badge{display:inline-block;border:1px solid #e7b9be;background:#fff0f2;color:#8f0a15;border-radius:99px;padding:4px 11px;font-size:12px;font-weight:700}.layout{display:grid;grid-template-columns:245px minmax(0,1fr);gap:34px;padding:28px 5vw 70px;max-width:1700px;margin:auto}.side{position:sticky;top:16px;align-self:start;max-height:calc(100vh - 32px);overflow:auto;border-right:1px solid var(--line);padding-right:18px}.side a{display:block;color:#39414b;text-decoration:none;font-size:12px;padding:6px 8px;border-radius:6px}.side a:hover{background:var(--soft);color:var(--red)}.side .navtitle{font-weight:750;font-size:12px;margin:14px 8px 5px}.main{min-width:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.card{border:1px solid var(--line);border-radius:12px;padding:17px;background:#fff}.card b{display:block;font-size:27px;color:var(--red)}.card span{font-size:12px;color:var(--muted)}.notice{border-left:4px solid var(--red);background:#fff5f5;padding:15px 18px;margin:20px 0;border-radius:0 8px 8px 0}.notice.dark{background:var(--ink);color:#fff;border-color:var(--gold)}.notice.dark p{color:#e2e5e9}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{border:1px solid var(--line);border-radius:12px;padding:20px}.panel h3{margin-top:0}.panel ul{padding-left:20px}.section{margin:34px 0}.section h2{font-size:26px;border-bottom:2px solid var(--red);padding-bottom:8px}.doc{padding:30px 0;border-top:1px solid var(--line);scroll-margin-top:18px}.doc h1{font-size:29px;line-height:1.2}.doc h2{font-size:22px;margin-top:28px}.doc h3{font-size:17px}.doc p,.doc li{overflow-wrap:anywhere}.doc pre{overflow:auto;background:#f5f6f8;border:1px solid var(--line);padding:16px;border-radius:9px;font-size:12px}.doc code{font-family:ui-monospace,Consolas,monospace;font-size:.9em}.doc blockquote{margin:16px 0;border-left:3px solid var(--gold);padding:8px 16px;background:#fbf9f5}.doc table,.reqtable{display:block;overflow:auto;width:100%;border-collapse:collapse;font-size:12px;margin:16px 0}.doc th,.doc td,.reqtable th,.reqtable td{border:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top;min-width:95px}.doc th,.reqtable th{background:var(--soft);position:sticky;top:0}.doc img{max-width:100%}.svgwrap{overflow:auto;border:1px solid var(--line);border-radius:10px;background:#fff;max-height:800px}.svgwrap svg{max-width:none;display:block}.diagram{margin:12px 0}details{border:1px solid var(--line);border-radius:10px;margin:10px 0;background:#fff}summary{cursor:pointer;padding:13px 16px;font-weight:700}details>img{display:block;max-width:100%;height:auto;margin:auto;padding:10px}details>p{padding:0 16px}.muted{color:var(--muted);font-size:12px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.controls input,.controls select{border:1px solid #b9c0c9;border-radius:7px;padding:9px 12px;font:inherit}.controls input{min-width:260px;flex:1}.reqwrap{max-height:620px;overflow:auto;border:1px solid var(--line);border-radius:10px}.reqtable{margin:0;display:table}.reqtable td:nth-child(3){min-width:360px}.footer{background:var(--ink);color:#d8dde3;padding:28px 5vw;font-size:13px}.footer strong{color:#fff}.pill{font-size:11px;background:#eef1f4;border-radius:5px;padding:2px 6px}.skip{position:absolute;left:-9999px}.skip:focus{left:10px;top:10px;background:#fff;padding:10px;z-index:9}@media(max-width:1000px){.layout{grid-template-columns:1fr}.side{position:static;max-height:none;border-right:0;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:3px;padding:0 0 14px}.side .navtitle{width:100%}.cards{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}}@media(max-width:560px){.hero{padding:30px 5vw}.top{font-size:11px}.cards{gap:8px}.card{padding:12px}.card b{font-size:23px}.layout{padding-top:18px}.doc h1{font-size:25px}}@media print{.side,.controls,.top{display:none}.layout{display:block;padding:0}.doc{break-before:page}.svgwrap{max-height:none}details{break-inside:avoid}.hero{padding:20px 0}body{font-size:11px}}
</style></head><body><a class="skip" href="#main">Skip to content</a><div class="top"><strong>Get Stoopy · Shop Smart. Live Better.</strong><span>Phase-1 review package · 2026-11-01</span></div><header class="hero"><span class="badge">PROPOSED · NOT IMPLEMENTED</span><h1>Architecture review,<br>before the first line of application code.</h1><p>A centralized, secure, AI-enabled multi-vendor marketplace design for Bangladesh-first launch. This package consolidates the recovered conversation, master instructions and six visual references into reviewable architecture, data, permission, API, security and delivery decisions.</p><p><strong>Review gate:</strong> approve or revise the proposed architecture before Phase 2. No paid resources, live payments, identity-document collection or production deployment are authorized by this document.</p></header><div class="layout"><nav class="side" aria-label="Review documents"><div class="navtitle">Start here</div><a href="#summary">Executive summary</a><a href="#decisions">Decisions to approve</a><a href="#diagrams">Architecture &amp; ERDs</a><a href="#screenshots">Screenshot inventory</a><a href="#requirements">Requirement register</a><div class="navtitle">Documents</div>'''+nav+'''</nav><main id="main" class="main"><section id="summary"><div class="eyebrow">Executive summary</div><h2>What is ready for review</h2><div class="cards"><div class="card"><b>'''+str(len(model['entities']))+'''</b><span>logical entities · no executable schema</span></div><div class="card"><b>'''+str(len(model['relations']))+'''</b><span>explicit logical relationships</span></div><div class="card"><b>'''+str(ops)+'''</b><span>proposed API operations · '''+str(len(api['paths']))+''' paths</span></div><div class="card"><b>'''+str(len(req))+'''</b><span>traceability rows · none implemented</span></div></div><div class="notice dark"><strong>Honest status</strong><p>The workspace originally contained references only. This is a Phase-1 design package, not a running marketplace. Document validation and diagram rendering are not application, security or payment tests. Phase 1 remains pending owner review; Phases 2–11 have not started.</p></div><div class="grid2"><div class="panel"><h3>Proposed core</h3><ul><li>Next.js BFF + one NestJS modular monolith + worker.</li><li>PostgreSQL/PostGIS, Prisma, scoped repositories + RLS.</li><li>Keycloak identity with opaque revocable sessions; mandatory privileged TOTP.</li><li>Immutable balanced finance journals; COD custody separate from earnings.</li><li>Recipient-first remote ordering; manual vendor ready; atomic 30-second rider offers.</li></ul></div><div class="panel"><h3>Critical risks</h3><ul><li>Marketplace fund custody / QR / payout authority is not established by a gateway logo.</li><li>Cross-scope leakage must be tested in APIs, reports, exports, caches, sockets and AI.</li><li>Money/assignment races require DB constraints, not frontend or Redis-only locks.</li><li>KYC/session compromise and insider exports need strict access, step-up and audit.</li><li>Browser capture prevention and background GPS have real platform limits.</li></ul></div></div><p class="muted">Source coverage: '''+str(counts['master'])+''' normalized master/Bengali lines, '''+str(counts['shared-conversation'])+''' historical additions, '''+str(counts['screenshot'])+''' screenshot inventory rows. The original master attachment was not independently archived; byte-for-byte fidelity is not claimed. Unavailable historical artifacts are disclosed.</p></section><section class="section" id="decisions"><h2>Decisions to approve</h2><ol><li><strong>Topology:</strong> Next.js BFF + NestJS modular monolith + worker, one business database.</li><li><strong>Identity:</strong> Keycloak operating cost vs maintained database-session auth alternative.</li><li><strong>Geography:</strong> separate Mymensingh City and Purbadhala pilot scopes; destination-based order visibility; explicit financial-scope anchor.</li><li><strong>Delivery/finance:</strong> store→recipient road-distance slabs, acceptance-time snapshot, Sunday cutoff/holiday policy, COD offset disclosure, commission precedence and vendor settlement hold.</li><li><strong>Providers:</strong> capability-gated adapters; QR/split settlement/disbursement disabled until contract/legal verification.</li><li><strong>Privacy/AI:</strong> consented first-party data, scoped read tools, human exact-action approval; no autonomous sensitive execution.</li><li><strong>Brand/client:</strong> approved red/white/black layout, mobile-first PWA, honest native/browser limitations.</li></ol><p>Architecture approval permits development with labelled test fixtures only. It does not approve paid services, real money or production.</p></section><section class="section" id="diagrams"><h2>Architecture &amp; ERDs</h2><div class="svgwrap">'''+svg_inline(D/'diagrams'/'system-architecture.svg')+'''</div><p class="muted">Proposed topology; nothing provisioned. Domain ERDs below are zoomable. Complete field definitions and retention/index proposals are in the data dictionary.</p>'''+diagrams+'''</section><section class="section" id="screenshots"><h2>Visual references</h2><p>These are the supplied images, not implemented screens. Sample amounts, addresses, ratings, payment logos and worldwide/free-shipping claims are not production facts. </p>'''+gallery+'''</section><section class="section" id="requirements"><h2>Requirement traceability</h2><p>Every row is a specification/design item, not a passed test. The CSV companion includes source line references, design documents and planned verification IDs. Search below; filtering happens locally without network access.</p><div class="controls"><label>Search <input id="reqsearch" type="search" placeholder="e.g. payout, TOTP, remote, red"></label><label>Source <select id="reqsource"><option value="">All sources</option><option value="master">Master / Bengali</option><option value="shared-conversation">Historical additions</option><option value="screenshot">Screenshots</option></select></label><span id="reqcount" class="pill"></span></div><div class="reqwrap"><table class="reqtable"><thead><tr><th>ID</th><th>Source</th><th>Requirement / instruction</th><th>Phase</th><th>Status</th></tr></thead><tbody id="reqbody">'''+reqrows+'''</tbody></table></div></section><section class="section"><div class="eyebrow">Full review documents</div><h2>Documentation</h2><p class="muted">The Markdown originals, OpenAPI YAML/JSON, CSV registers, logical model JSON and diagram sources are included in the companion ZIP. External citations require internet; the review itself is self-contained.</p></section>'''+docsections+'''</main></div><footer class="footer"><strong>Get Stoopy · Shop Smart. Live Better.</strong><br>Phase-1 architecture review draft. No application acceptance is claimed. Production deployment requires separate explicit authorization.</footer><script>
(function(){const q=document.getElementById('reqsearch'),s=document.getElementById('reqsource'),rows=Array.from(document.querySelectorAll('#reqbody tr')),count=document.getElementById('reqcount');function filter(){const term=q.value.toLowerCase().trim(),source=s.value;let n=0;rows.forEach(r=>{const ok=(!term||r.textContent.toLowerCase().includes(term))&&(!source||r.dataset.source===source);r.hidden=!ok;if(ok)n++;});count.textContent=n+' / '+rows.length+' rows';}q.addEventListener('input',filter);s.addEventListener('change',filter);filter();})();
</script></body></html>'''
(R/'architecture-review.html').write_text(page)
print('Review HTML bytes:',len(page.encode()),'role matrix rows:',len(rows))
